STAGES = {
0: ('A', 'Planning and evidence infrastructure'),
1: ('B', 'Required CPU foundation repairs'),
2: ('C', 'Evidence, retrieval and performance refinement'),
3: ('D', 'Private PDF workspace, OCR and formulas'),
4: ('E', 'Governed assembly and inactive central integration'),
5: ('F', 'Optional local transcript and business capabilities'),
6: ('G', 'Independent qualification and controlled release'),
7: ('H', 'Deferred commissioning boundaries'),
}
P0 = {'CORE-01','CORE-02','CORE-03','CORE-04','CORE-11','CORE-13','CORE-16'}
cards = []
for line in ROWS.strip().splitlines():
    key, stage, finding, title, scope, acceptance, deps = line.split('|')
    stage = int(stage)
    cards.append(dict(id=f'NSAI-{len(cards)+1:03}', key=key, stage=stage, finding_ids=[finding], title=title,
        disposition='DEFERRED_NO_ACTIVATION' if stage == 7 else ('OPTIONAL_AFTER_BASELINE' if stage == 5 else 'REQUIRED'),
        status='EXTERNAL_PREREQUISITE' if key=='security-worker' else 'PLANNED',
        priority='P0' if finding in P0 else ('P1' if stage<=2 else 'P2'),
        scope=scope.split('; '), acceptance_criteria=acceptance.split('; '), dependency_keys=[d for d in deps.split(',') if d],
        owner_role='Implementation engineer; independent verifier accepts',
        evidence_directory=f'evidence/implementation/NSAI-{len(cards)+1:03}/',
        execution_authority='Planning only in this delivery; later implementation follows authorized scope. Deferred activation requires new explicit instruction.',
        rollback='Revert only this change/image; restore compatible projection/configuration. For schema changes use tested compatibility path or protected restore. Preserve original records, audit events and user volumes.',
        completion_rule='All dependencies accepted, every criterion evidenced against exact source/image/configuration, independent review complete, no unresolved required regression. File presence and historical PASS do not qualify.',
        estimate='Size after inspecting actual change and fixture scope; do not promise time from audit measurements. Split if independently recoverable changes exceed one reviewable patch.'
    ))
lookup = {c['key']:c for c in cards}
for c in cards:
    c['dependencies']=[lookup[k]['id'] for k in c.pop('dependency_keys')]
    c['implementation_steps']=[
        f"Reproduce or specify the current contract in {', '.join(c['scope'])}; freeze the audit fixture and relevant source hashes.",
        f"Write the smallest independent specification for: {c['title']}. Review authority, byte/token/time/resource budgets, data lineage and backward compatibility before coding.",
        'Implement incrementally in the listed surfaces. Use original synthetic or authorized fixtures; add focused positive, negative, boundary, retry and cancellation cases appropriate to the acceptance criteria.',
        'Run targeted checks in owned disposable resources; compare source/output identities and relevant quality/performance contracts. Preserve failures and explain any scope changes.',
        'Have an independent verifier review fresh results, recovery and remaining limitations; update the status and evidence links only after acceptance. Deploy through the release gate, not directly from a card.'
    ]
    if c['stage']==7:
        c['implementation_steps']=['Record the interface/disposition and prerequisites only.', 'Keep code paths, provider activation, generated execution and central enable disabled.', 'Reopen as a separately authorized implementation epic after the listed local gates and selected workload.']
    c['evidence_required']=['receipt.json: source/image/configuration/input hashes, UTC time, tool/runtime versions, command and exit status, isolation scope', 'cases.json: each acceptance criterion, expected/actual result, positive and adversarial cases, retained failures', 'review.md: independent decision, capability limits, privacy/provenance review and recovery result', 'metrics.json where relevant: units, cohorts, sample counts, cold/warm/concurrency labels and paired baseline/challenger measurements']

