RULES=[('ocr|pdf|page|rendered ast','pdf-viewer,ocr-quality,ocr-geometry,ocr-metrics'),('formula|calculation','formula-contract,formula-check'),('budget|cost|pricing','resource-ledger,token-admission,settlement'),('metric|utilization|throughput|freshness|assurance|drift','metric-lineage,refinement-gate'),('transcript|speaker|question|quantity|normalization','transcript-contract,transcript-linkage,source-map'),('continuity|recurr|handoff|session_context','continuity,ui-order'),('registry|manifest|schema|builder|authoring|procedure|flow','data-registry,capabilities,stage-dag'),('learning|holdout|promotion|training|outcome','learning-gates,business-outcomes'),('authority|permission|policy|governance|admin|secret|portal_auth','admin-local,central-contract,integration-secrets'),('memory|context|knowledge|retrieval|citation','canon-relevance,retrieval,pdf-scope'),('feedback|quality_signals|correction','correction-queue'),('evidence|trace|report|audit|scanner|certification','trace-projection,evidence,security-scan'),('retention','retention'),('worker|orchestration|job|dag','ocr-job,stage-dag'),('voice|crm|cloud|device|gpu|compute|script-execution|scorm|quizz|infrastructure|dynamics|compatibility','enterprise-defer,optional-providers')]
references=[]
for filename in ['REFERENCE_REMY.md','REFERENCE_REMY_CAPABILITIES.md','REFERENCE_PX_DVA.md','REFERENCE_PX_BROAD.md','REFERENCE_DVA_BROAD.md']:
    content=(ROOT/'docs/audit'/filename).read_text(encoding='utf-8')
    # Markdown tables can wrap across physical lines; combine continuations.
    joined=[]; pending=''
    for line in content.splitlines():
        if line.startswith('|'):
            if pending:joined.append(pending)
            pending=line.strip()
        elif pending and line.strip() and not line.startswith('#'):
            pending+=' '+line.strip()
        else:
            if pending:joined.append(pending);pending=''
    if pending:joined.append(pending)
    for row in joined:
        if re.match(r'^\|\s*[-:]+',row):continue
        if not row.endswith('|'):row=row.split(' |')[0]+' |'
        parts=[p.strip() for p in row.strip('|').split('|')]
        if not parts or parts[0].lower() in {'module','surface','inspected reference','observed interface/body','canonical module','stage','reference','capability','area','candidate','feature','metric','test','category'}:continue
        keys=[]
        for pattern,targets in RULES:
            if re.search(pattern,row,re.I):keys.extend(targets.split(','))
        keys=list(dict.fromkeys(keys or ['capabilities','enterprise-defer']))
        rid=f'ADOPT-{len(references)+1:03}'
        references.append(dict(id=rid,source=f'docs/audit/{filename}',reference_row=row,card_ids=[lookup[k]['id'] for k in keys],decision='INDEPENDENT_SPECIFICATION_ONLY; metadata-only/module rows are screening scope, not validated functionality; optional and deferred card boundaries apply',approval_required_before_source_copy='Source copying is prohibited; architecture-only implementation and original fixtures.'))
dump(OUT/'reference-adoptions.json',references)
dump(OUT/'finding-coverage.json',findings)

def allocate_text(text):
    keys=[]
    for pattern,targets in RULES:
        if re.search(pattern,text,re.I):keys.extend(targets.split(','))
    if re.search('embedding|semantic.index|hybrid',text,re.I):keys.append('semantic-index')
    if re.search('bitemporal|temporal|historical validity',text,re.I):keys.append('temporal-memory')
    if re.search('signed|anchor',text,re.I):keys.append('signed-anchor')
    return [lookup[k]['id'] for k in dict.fromkeys(keys or ['capabilities','enterprise-defer'])]

