ids={c['id'] for c in cards}; assert len(ids)==len(cards)
done=set(); visiting=set()
def visit(cid):
    assert cid in ids
    if cid in done:return
    assert cid not in visiting, f'Cycle at {cid}'
    visiting.add(cid)
    for dep in next(c for c in cards if c['id']==cid)['dependencies']:visit(dep)
    visiting.remove(cid);done.add(cid)
for cid in ids:visit(cid)
